// Localization catalogs of the extension (E11-i18n): the exporter of the base bundle and the check
// that every published language is complete.
//
// Two kinds of catalog, both found BY FILE NAME (no language list lives in the code):
//   package.nls.json            base (English), written by hand; keys are the `%key%` of package.json
//   package.nls.<id>.json       one per language
//   l10n/bundle.l10n.json       base of the code texts, GENERATED by `export`; never edited by hand
//   l10n/bundle.l10n.<id>.json  one per language, same keys in the same order as the base
// `<id>` is the `languageId` of the VS Code language pack, lowercase (`es`, `pt-br`, `zh-cn`):
// VS Code looks the files up by that id (verified in microsoft/vscode `extHostLocalizationService.ts`
// and `extensionsScannerService.ts`, read 04/11/2026). Adding a language is adding the two files.
//
// Usage:
//   node scripts/l10n.mjs export [root]   rewrites l10n/bundle.l10n.json from the sources
//   node scripts/l10n.mjs check [root]    exit 0 when every catalog is consistent, 1 with one line per
//                                         problem otherwise. `root` defaults to the repository.
// ASCII only on purpose: it prints to Windows consoles with arbitrary code pages.

import { getL10nJson } from '@vscode/l10n-dev';
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

/** Source roots the exporter reads, relative to the repository root. */
const SOURCE_DIRS = [join('src', 'extension'), join('webview-ui', 'src')];

/** A path is not a source of visible texts when it is a test, a fixture or the test helper. */
const EXCLUDED = [/\.test\.[cm]?[jt]sx?$/, /(^|\/)test-fixtures\//, /(^|\/)testing\.tsx$/];

/** Language ids are lowercase letters, digits and `-` (`pt-br`). */
const LANGUAGE_ID = /^[a-z0-9]+(-[a-z0-9]+)*$/;

/**
 * Lists the `.ts` and `.tsx` files under `dir` that can carry visible texts, as `/`-separated paths
 * relative to `root`, sorted by code point so the bundle order does not depend on the file system.
 */
function collectSources(root) {
  const found = [];
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (entry.name !== 'node_modules') walk(full);
        continue;
      }
      const rel = relative(root, full).replaceAll('\\', '/');
      if (!/\.tsx?$/.test(rel) || /\.d\.ts$/.test(rel)) continue;
      if (EXCLUDED.some((pattern) => pattern.test(rel))) continue;
      found.push(rel);
    }
  };
  for (const dir of SOURCE_DIRS) {
    const full = join(root, dir);
    if (existsSync(full)) walk(full);
  }
  return found.sort();
}

/** True when `root` has any of the source directories (a bare catalog directory has none). */
function hasSources(root) {
  return SOURCE_DIRS.some((dir) => existsSync(join(root, dir)));
}

/**
 * Extracts the base bundle from the sources: every `l10n.t(...)` call of a file that imports
 * `@vscode/l10n` or `vscode` (the only files `@vscode/l10n-dev` reads, and only the namespace form
 * `l10n.t(`; ESLint forbids the named import so nothing escapes). Returns the key to value map
 * in code order, grouped by file. A template literal with `${}` inside `t` makes l10n-dev throw,
 * which is the intended rejection.
 * VERIFIED on Windows 11 with Node 24.22 (04/11/2026): the wasm parser of l10n-dev loads and
 * extracts `l10n.t` calls, both from `node scripts/l10n.mjs export` and from the spawned `check` of
 * `l10nCatalog.test.ts` ("fails when the base bundle is out of date with the sources, and passes
 * once it is not"). Only the `node scripts/l10n.mjs` CLI is exercised, not the Vitest process
 * itself; macOS and Linux UNVERIFIED until CI.
 */
async function extractBundle(root) {
  const files = collectSources(root).map((rel) => ({
    extension: rel.slice(rel.lastIndexOf('.')),
    contents: readFileSync(join(root, rel), 'utf8'),
  }));
  return files.length === 0 ? {} : await getL10nJson(files);
}

/** The text of a bundle entry: a string, or the `message` of the `{ message, comment }` form. */
function messageOf(value) {
  return typeof value === 'string' ? value : value.message;
}

/**
 * The tokens a translation must keep intact, sorted: the `{...}` placeholders, the
 * `(command:...)` links of a welcome view and the `#setting.id#` references of a Markdown
 * description. Compared as a multiset, so a translator may reorder them but not drop or edit one.
 */
function tokensOf(text) {
  const matches = text.match(/\{[^{}]*\}|\(command:[^)]*\)|#openVsCode\.[\w.]+#/g) ?? [];
  return [...matches].sort();
}

/** Reads a JSON object file; returns `{ value }` or `{ error }` (never throws). */
function readCatalog(file) {
  try {
    const value = JSON.parse(readFileSync(file, 'utf8'));
    if (typeof value !== 'object' || value === null || Array.isArray(value)) {
      return { error: `${file}: must be a JSON object` };
    }
    return { value };
  } catch (error) {
    return { error: `${file}: cannot be read as JSON (${error.message})` };
  }
}

/** Every string of the manifest that is exactly `%key%`, which is what VS Code substitutes. */
function nlsKeysOf(manifest) {
  const keys = new Set();
  const visit = (node) => {
    if (typeof node === 'string') {
      const match = /^%([\w.-]+)%$/.exec(node);
      if (match) keys.add(match[1]);
    } else if (Array.isArray(node)) node.forEach(visit);
    else if (node !== null && typeof node === 'object') Object.values(node).forEach(visit);
  };
  visit(manifest);
  return keys;
}

/**
 * Compares one translated catalog with its base, pushing one message per difference: missing
 * keys, extra keys, order (bundles only), empty values and altered tokens.
 */
function compareCatalog(label, base, translated, problems, { ordered }) {
  const baseKeys = Object.keys(base);
  const keys = Object.keys(translated);
  for (const key of baseKeys) {
    if (!(key in translated)) problems.push(`${label}: missing key ${JSON.stringify(key)}`);
  }
  for (const key of keys) {
    if (!(key in base)) problems.push(`${label}: extra key ${JSON.stringify(key)}`);
  }
  if (
    ordered &&
    keys.length === baseKeys.length &&
    keys.every((key) => key in base) &&
    keys.some((key, i) => key !== baseKeys[i])
  ) {
    problems.push(`${label}: keys are not in the order of the base bundle`);
  }
  for (const key of keys) {
    if (!(key in base)) continue;
    const text = translated[key];
    if (typeof messageOf(text ?? '') !== 'string' || messageOf(text).trim() === '') {
      problems.push(`${label}: empty or non-string value for ${JSON.stringify(key)}`);
      continue;
    }
    const want = tokensOf(messageOf(base[key])).join(' ');
    const got = tokensOf(messageOf(text)).join(' ');
    if (want !== got) {
      problems.push(
        `${label}: placeholders or links differ for ${JSON.stringify(key)} (base: ${want || 'none'}; translation: ${got || 'none'})`,
      );
    }
  }
}

/** Language ids found in `dir` for files named `<prefix>.<id>.json`, plus the ones that break the id rule. */
function languagesIn(dir, prefix, problems) {
  const ids = new Set();
  if (!existsSync(dir)) return ids;
  for (const name of readdirSync(dir)) {
    const match = new RegExp(`^${prefix.replaceAll('.', '\\.')}\\.([^.]+)\\.json$`).exec(name);
    if (!match) continue;
    if (!LANGUAGE_ID.test(match[1])) {
      problems.push(`${join(dir, name)}: the language id "${match[1]}" must be lowercase`);
      continue;
    }
    ids.add(match[1]);
  }
  return ids;
}

/**
 * Runs every consistency check on the catalogs under `root` and returns the problems, one string
 * each (empty array when all is well):
 * - `package.nls.json` has exactly the `%key%` strings of `package.json`;
 * - `l10n/bundle.l10n.json` equals what the sources export (skipped when `root` has no
 *   `src/extension` nor `webview-ui/src`, as in the temporary directories of the tests);
 * - each language has BOTH files (manifest and bundle), with the same keys, in the same order
 *   (bundle), non-empty values and the same placeholders and links.
 */
export async function checkCatalogs(root) {
  const problems = [];
  const manifest = readCatalog(join(root, 'package.json'));
  if (manifest.error) return [manifest.error];

  const nlsBase = readCatalog(join(root, 'package.nls.json'));
  if (nlsBase.error) problems.push(nlsBase.error);
  else {
    const wanted = nlsKeysOf(manifest.value);
    const have = new Set(Object.keys(nlsBase.value));
    for (const key of wanted) {
      if (!have.has(key))
        problems.push(`package.nls.json: missing key "${key}" used by package.json`);
    }
    for (const key of have) {
      if (!wanted.has(key))
        problems.push(`package.nls.json: key "${key}" is not used by package.json`);
    }
  }

  const bundleBase = readCatalog(join(root, 'l10n', 'bundle.l10n.json'));
  if (bundleBase.error) problems.push(bundleBase.error);
  else if (hasSources(root)) {
    const expected = await extractBundle(root);
    if (JSON.stringify(expected) !== JSON.stringify(bundleBase.value)) {
      const a = Object.keys(expected);
      const b = Object.keys(bundleBase.value);
      const missing = a.filter((key) => !b.includes(key));
      const orphan = b.filter((key) => !a.includes(key));
      problems.push(
        `l10n/bundle.l10n.json is not up to date with the code (${missing.length} new, ${orphan.length} stale, or a changed order): run "npm run l10n:export"`,
      );
    }
  }

  const nlsIds = languagesIn(root, 'package.nls', problems);
  const bundleIds = languagesIn(join(root, 'l10n'), 'bundle.l10n', problems);
  for (const id of nlsIds) {
    if (!bundleIds.has(id))
      problems.push(`language "${id}": package.nls.${id}.json has no l10n/bundle.l10n.${id}.json`);
  }
  for (const id of bundleIds) {
    if (!nlsIds.has(id))
      problems.push(`language "${id}": l10n/bundle.l10n.${id}.json has no package.nls.${id}.json`);
  }
  for (const id of nlsIds) {
    const file = readCatalog(join(root, `package.nls.${id}.json`));
    if (file.error) problems.push(file.error);
    else if (!nlsBase.error) {
      compareCatalog(`package.nls.${id}.json`, nlsBase.value, file.value, problems, {
        ordered: false,
      });
    }
  }
  for (const id of bundleIds) {
    const file = readCatalog(join(root, 'l10n', `bundle.l10n.${id}.json`));
    if (file.error) problems.push(file.error);
    else if (!bundleBase.error) {
      compareCatalog(`l10n/bundle.l10n.${id}.json`, bundleBase.value, file.value, problems, {
        ordered: true,
      });
    }
  }
  return problems;
}

/** Rewrites `l10n/bundle.l10n.json` under `root` from the sources: 2 spaces, LF, final newline. */
export async function exportBundle(root) {
  const bundle = await extractBundle(root);
  const target = join(root, 'l10n', 'bundle.l10n.json');
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, `${JSON.stringify(bundle, null, 2)}\n`);
  return Object.keys(bundle).length;
}

/**
 * Entry point: `export` or `check`, on the repository or on the `root` named second. Sets
 * `process.exitCode` instead of exiting so stdout is flushed on every platform.
 */
async function main() {
  const [command, rootArg] = process.argv.slice(2);
  const root = resolve(rootArg ?? join(dirname(fileURLToPath(import.meta.url)), '..'));
  if (command === 'export') {
    const count = await exportBundle(root);
    console.log(`OK: l10n/bundle.l10n.json written with ${count} keys`);
  } else if (command === 'check') {
    if (!existsSync(root) || !statSync(root).isDirectory()) {
      console.error(`ERROR: ${root} is not a directory`);
      process.exitCode = 1;
      return;
    }
    const problems = await checkCatalogs(root);
    if (problems.length > 0) {
      for (const problem of problems) console.error(`ERROR: ${problem}`);
      process.exitCode = 1;
      return;
    }
    console.log('OK: catalogs are consistent');
  } else {
    console.error('Usage: node scripts/l10n.mjs <export|check> [root]');
    process.exitCode = 1;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  await main();
}
